import re

filepath = 'strategies/backtest/renko_smiio_supertrend_strategy.py'
with open(filepath, 'r') as f:
    content = f.read()

new_method = '    def generate_signals(self) -> list:\n        df = self._build_renko_df()\n        timestamps = df["timestamp"].values\n        n = len(df)\n        box = self.renko_box\n        closes    = df["renko_close"].values\n        renko_dir = df["renko_dir"].values\n        st_ind = SupertrendIndicator(atr_period=self.st_atr_length, factor=self.st_factor)\n        df_st  = st_ind.calculate(df)\n        st_dir = df_st["st_dir"].values\n        smi, sig = compute_smiio(closes, short_len=self.smiio_shortlen, long_len=self.smiio_longlen, signal_len=self.smiio_siglen)\n        signals = []\n        current_direction = None\n        pending = None\n        last_exit_bar = -1\n        for i in range(1, n):\n            ts = str(pd.Timestamp(timestamps[i]).strftime("%Y-%m-%dT%H:%M:%S"))\n            close = closes[i]\n            r_dir = renko_dir[i]\n            st = st_dir[i]\n            prev_st = st_dir[i - 1]\n            smi_cross_up   = smi[i] > sig[i] and smi[i-1] <= sig[i-1]\n            smi_cross_down = smi[i] < sig[i] and smi[i-1] >= sig[i-1]\n            st_flip_green  = prev_st == 1 and st == -1\n            st_flip_red    = prev_st == -1 and st == 1\n            if current_direction == "long":\n                if (st_flip_red and r_dir == -1) or (smi_cross_down and r_dir == -1):\n                    signals.append({"signal_type": "EXIT", "price": self._apply_slippage(close, "long", False), "timestamp": ts, "sl_price": close - box, "entry_type": "", "exit_type": "ST_FLIP_RED" if st_flip_red else "SMIIO_CROSS_DOWN", "direction": "long"})\n                    current_direction = None\n                    pending = None\n                    last_exit_bar = i\n            elif current_direction == "short":\n                if (st_flip_green and r_dir == 1) or (smi_cross_up and r_dir == 1):\n                    signals.append({"signal_type": "EXIT", "price": self._apply_slippage(close, "short", False), "timestamp": ts, "sl_price": close + box, "entry_type": "", "exit_type": "ST_FLIP_GREEN" if st_flip_green else "SMIIO_CROSS_UP", "direction": "short"})\n                    current_direction = None\n                    pending = None\n                    last_exit_bar = i\n            if current_direction is None and i > last_exit_bar:\n                if smi_cross_up:\n                    pending = {"side": "long", "bar": i}\n                elif smi_cross_down:\n                    pending = {"side": "short", "bar": i}\n            if pending is not None and current_direction is None and i > last_exit_bar:\n                side = pending["side"]\n                bars_since = i - pending["bar"]\n                if bars_since > 1:\n                    pending = None\n                elif side == "long" and r_dir == 1:\n                    signals.append({"signal_type": "ENTRY", "price": self._apply_slippage(close, "long", True), "timestamp": ts, "sl_price": close - box * 2, "entry_type": "BUY", "exit_type": "", "direction": "long"})\n                    current_direction = "long"\n                    pending = None\n                elif side == "short" and r_dir == -1:\n                    signals.append({"signal_type": "ENTRY", "price": self._apply_slippage(close, "short", True), "timestamp": ts, "sl_price": close + box * 2, "entry_type": "SELL", "exit_type": "", "direction": "short"})\n                    current_direction = "short"\n                    pending = None\n        return signals'

pattern = r'    def generate_signals\(self\).*?return signals'
new_content = re.sub(pattern, new_method, content, flags=re.DOTALL)

with open(filepath, 'w') as f:
    f.write(new_content)

print('Fix applied successfully')
